(function(E){ const x = E["sales-m2"] = E["sales-m2"] || {units:{}}; x.units["sales-2-2"] = {"grammar":{"id":"c-sales-2-2-g","level":"B1","course":"sales","unit":"sales-2-2","title":"Comparing terms: cheaper than, not as safe as","titleTr":"Koşulları karşılaştırmak: cheaper than, not as safe as","titleFa":"مقایسه‌ی شرایط: cheaper than، not as safe as","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["short adjective + -er than","cheaper than, safer than"],["more + long adjective + than","more expensive than"],["(not) as + adjective + as","not as safe as cash in advance"],["twice / three times as ... as","twice as long as"]]},"wrong":"An FOB price is more cheap than a CIF price.","right":"An FOB price is cheaper than a CIF price.","blank":{"sentence":"A shipment by sea takes almost twice as ___ as a shipment by road.","word":"long","distractors":["longer","longest"]},"wrong2":"Open account is not as safe than an L/C.","right2":"Open account is not as safe as an L/C.","blank2":{"sentence":"For the seller, an L/C is ___ than open account.","word":"safer","distractors":["safe","safest"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"To compare, add -er + than to short adjectives.","tr":"Karşılaştırmak için kısa sıfatlara -er + than ekle.","fa":"برای مقایسه، به صفت کوتاه er اضافه کن و بعد than بیاور.","ex":"cheaper than, safer than"},{"en":"Long adjectives can't take -er, so use more ... than.","tr":"Uzun sıfatlar -er almaz; bu yüzden more ... than kullan.","fa":"صفت بلند er نمی‌گیرد، پس قبلش more و بعدش than بیاور.","ex":"more expensive than an FOB price"},{"en":"For equal or less, use (not) as + adjective + as.","tr":"Eşitlik ya da daha az için (not) as + sıfat + as kullan.","fa":"برای «به همان اندازه» یا «کمتر از»، صفت را بین (not) as و as بگذار.","ex":"Open account is not as safe as an L/C."}],"test":{"en":"Count the syllables. One (or ending in -y)? Add -er. Three or more? Use more. Never both.","tr":"Heceleri say. Tek heceli mi (ya da -y ile mi bitiyor)? -er ekle. Üç ya da daha fazla mı? more kullan. Asla ikisini birden kullanma.","fa":"هجاها را بشمار. یک‌هجایی است (یا به ‎-y ختم می‌شود)؟ ‎-er اضافه کن. سه هجا یا بیشتر؟ more بیاور. هرگز هر دو را با هم نیاور."},"contrast":{"en":"Turkish 'daha' and Persian «تر» work with every adjective, so learners write 'more thick'. English chooses: -er for short words, more for long ones.","tr":"Türkçede her sıfat için 'daha' kullanırız: 'daha kalın', 'daha pahalı'. Bu yüzden İngilizcede 'more thick' ya da 'more thicker' yazılıyor. İngilizce seçer: kısa kelimelere -er, uzun kelimelere more.","fa":"در فارسی به هر صفتی «تر» اضافه می‌کنیم: «ضخیم‌تر»، «گران‌تر». برای همین خیلی از ما می‌نویسیم more thick یا more thicker. انگلیسی فرق می‌گذارد: کلمه‌ی کوتاه er می‌گیرد و قبل از کلمه‌ی بلند more می‌آید."}},"errorWatch":[{"find":["more thicker","more heavier","more cheaper","more better","more bigger","more softer","more lighter","more thick than","more heavy than","more cheap than","more soft than","more light than"],"fix":{"en":"Short adjectives take -er, without more: 'thicker than', 'cheaper than'.","tr":"Kısa sıfatlar more olmadan -er alır: 'thicker than', 'cheaper than'.","fa":"صفت‌های کوتاه بدون more، ‎-er می‌گیرند: thicker than و cheaper than."}},{"find":["as cheap than","as long than","as good than","as heavy than","as soft than","as expensive than"],"fix":{"en":"as ... as, never as ... than: 'not as cheap as'.","tr":"as ... as olur, asla as ... than değil: 'not as cheap as'.","fa":"شکل درست as ... as است، نه as ... than: not as cheap as."}}]},"b2":{"id":"c-sales-2-2-b2","level":"B2","track":"B2","course":"sales","unit":"sales-2-2","title":"How big is the difference? slightly, much, far","titleTr":"Fark ne kadar büyük? slightly, much, far","titleFa":"تفاوت چقدر است؟ slightly، much، far","formsTable":{"headers":{"en":["How big?","Word","Example"],"tr":["Ne kadar?","Kelime","Örnek"],"fa":["چقدر؟","کلمه","مثال"]},"rows":[["small","slightly / a little / a bit","slightly more expensive per kilo"],["big","much / far / a lot / considerably","far safer for the seller"],["never","very + comparative","not: very cheaper"]]},"wrong":"Per kilo, FOB is very cheaper than DAP.","right":"Per kilo, FOB is much cheaper than DAP.","blank":{"sentence":"Per kilo, CIF is ___ more expensive, but you don't have to book the ship.","word":"slightly","distractors":["very","too"]},"wrong2":"The freight is a lot of lower this month.","right2":"The freight is a lot lower this month.","blank2":{"sentence":"An L/C is ___ safer than open account for an exporter.","word":"far","distractors":["very","so more"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Small difference: slightly / a little / a bit + comparative.","tr":"Küçük fark: slightly / a little / a bit + karşılaştırma.","fa":"برای تفاوت کم، قبل از صفت تفضیلی slightly، a little یا a bit بیاور.","ex":"slightly more expensive"},{"en":"Big difference: much / far / a lot + comparative.","tr":"Büyük fark: much / far / a lot + karşılaştırma.","fa":"برای تفاوت زیاد، قبل از صفت تفضیلی much، far یا a lot بیاور.","ex":"far safer, a lot lower"},{"en":"Never very + comparative, never a lot of + comparative.","tr":"Asla very + karşılaştırma, asla a lot of + karşılaştırma.","fa":"قبل از صفت تفضیلی هرگز very یا a lot of نیاور.","ex":"much cheaper, not very cheaper"}],"test":{"en":"Can you put 'very' in front? Then it is not a comparative. With -er or more, use much or slightly instead.","tr":"Önüne 'very' koyabiliyor musun? O zaman karşılaştırma sıfatı değildir. -er ya da more varsa onun yerine much ya da slightly kullan.","fa":"می‌توانی very را جلویش بگذاری؟ پس صفت تفضیلی نیست. اگر ‎-er یا more دارد، به جایش much یا slightly بیاور."},"contrast":{"en":"Turkish says 'çok daha ucuz' and Persian «خیلی ارزان‌تر», where 'çok' and «خیلی» look like 'very'. In English, 'very' does not work here: use much or far.","tr":"Türkçede 'çok daha ucuz' denir; 'çok' burada 'very' gibi görünür. İngilizcede 'very' burada olmaz: much ya da far kullan.","fa":"در فارسی می‌گوییم «خیلی ارزان‌تر» و «خیلی» شبیه very به نظر می‌رسد. در انگلیسی very اینجا درست نیست: much یا far به کار ببر."}},"errorWatch":[{"find":["very cheaper","very better","very more","very lower","very longer","very safer"],"fix":{"en":"Use much, far or slightly with a comparative: 'much cheaper', 'slightly more expensive'.","tr":"Karşılaştırmayla much, far ya da slightly kullan: 'much cheaper', 'slightly more expensive'.","fa":"با صفت تفضیلی much، far یا slightly بیاور: «much cheaper»، «slightly more expensive»."}},{"find":["a lot of lower","a lot of higher","a lot of cheaper","a lot of better","a lot of longer"],"fix":{"en":"No 'of' before a comparative: 'a lot lower'.","tr":"Karşılaştırmadan önce 'of' gelmez: 'a lot lower'.","fa":"قبل از صفت تفضیلی of نمی‌آید: «a lot lower»."}}],"useIn":{"en":"B2: make one comparison exact with slightly, much or far.","tr":"B2: bir karşılaştırmayı slightly, much ya da far ile kesinleştir.","fa":"مسیر B2: یکی از مقایسه‌ها را با slightly، much یا far دقیق کن."},"exitItem":{"from":"sales-2-2","kind":"blank","prompt":"Our lead time is ___ shorter than last year: only two days less.","options":["very","a little","more"],"correct":1,"why":{"en":"a little: the difference is small, two days. 'Very' can't go before 'shorter', and 'more shorter' is wrong.","tr":"a little: fark küçük, iki gün. 'Very' 'shorter'dan önce gelmez; 'more shorter' da yanlıştır.","fa":"a little درست است، چون فرق کم است، فقط دو روز. very قبل از shorter نمی‌آید و more shorter هم غلط است."}}},"vocab":{"id":"c-sales-2-2-v","level":"B1","category":"vocab","course":"sales","unit":"sales-2-2","goals":["career"],"title":{"en":"Delivery and payment","tr":"Teslimat ve ödeme","fa":"تحویل و پرداخت"},"cards":[{"word":"Incoterms","sentence":"Incoterms say who pays for what on the way.","meaning":{"en":"ICC rules on who pays and who carries the risk in delivery.","tr":"teslim şartları kuralları (Incoterms)","fa":"قواعد اینکوترمز: چه کسی هزینه می‌دهد و ریسک با کیست"}},{"word":"freight","sentence":"Freight is often the second biggest cost.","meaning":{"en":"The price of carrying goods; also the goods carried.","tr":"navlun, taşıma ücreti","fa":"کرایه‌ی حمل"}},{"word":"cargo insurance","sentence":"The buyer arranges cargo insurance under FOB.","meaning":{"en":"Cover against loss or damage on the way.","tr":"kargo sigortası","fa":"بیمه‌ی محموله"}},{"word":"port of loading","sentence":"Our port of loading is Mersin.","meaning":{"en":"The port where goods go on the ship.","tr":"yükleme limanı","fa":"بندر بارگیری"}},{"word":"carrier","sentence":"The carrier collects the container on Monday.","meaning":{"en":"The company that moves the goods.","tr":"taşıyıcı","fa":"شرکت حمل‌کننده"}},{"word":"cash in advance","sentence":"New customers pay cash in advance for the first order.","meaning":{"en":"Payment before the goods are sent.","tr":"peşin ödeme","fa":"پیش‌پرداخت کامل"}},{"word":"letter of credit","sentence":"Their bank opened a letter of credit for us.","meaning":{"en":"A bank's promise to pay when the right documents arrive.","tr":"akreditif","fa":"اعتبار اسنادی (ال‌سی)"}},{"word":"documentary collection","sentence":"Banks handle a documentary collection, but they don't promise payment.","meaning":{"en":"Banks hand over documents when the buyer pays or accepts a bill.","tr":"vesaik mukabili ödeme","fa":"وصول اسنادی"}},{"word":"open account","sentence":"Long-term customers can buy on open account.","meaning":{"en":"The buyer pays after receiving the goods.","tr":"açık hesap","fa":"حساب باز (پرداخت پس از دریافت کالا)"}},{"word":"compare","sentence":"Always compare offers on the same terms.","gap":"compare","accept":["compare"],"meaning":{"en":"To look at how two things are alike or different.","tr":"karşılaştırmak","fa":"مقایسه کردن"}}]},"judge":{"id":"c-sales-2-2-j","course":"sales","unit":"sales-2-2","type":"judge","title":{"en":"Is this term clear?","tr":"Bu koşul net mi?","fa":"این شرط روشن است؟"},"prompt":"Four lines from offers for 20 pallets of dates.","parts":["Rule and place","Year","Payment clear"],"instruction":{"en":"Tap what each line has. The line to use has all three.","tr":"Her satırda ne olduğuna dokun. Kullanılacak satırda üçü de var.","fa":"روی چیزهایی که هر خط دارد بزن. خطی که باید به کار ببری هر سه را دارد."},"items":[{"by":"New rep","answer":"Delivery by ship, payment after delivery if possible.","present":[],"fix":{"en":"No rule, no place, and 'if possible' promises nothing. Write 'FOB Bandar Abbas, Incoterms 2020' and a real payment term.","tr":"Kural yok, yer yok ve 'if possible' hiçbir şey vaat etmez. 'FOB Bandar Abbas, Incoterms 2020' ve gerçek bir ödeme koşulu yaz.","fa":"نه قاعده دارد، نه محل، و «if possible» قولی نمی‌دهد. بنویس «FOB Bandar Abbas, Incoterms 2020» و یک شرط پرداخت واقعی."}},{"by":"Sales rep","answer":"FOB Bandar Abbas. Payment: 50% now.","present":["Rule and place"],"fix":{"en":"A rule and a place, but no year, and where is the other 50%? Add 'Incoterms 2020' and when the balance is due.","tr":"Kural ve yer var ama yıl yok; peki kalan %50 ne olacak? 'Incoterms 2020' ekle ve kalanın ne zaman ödeneceğini yaz.","fa":"قاعده و محل دارد، ولی سال نه؛ ۵۰ درصد بقیه چه می‌شود؟ «Incoterms 2020» را اضافه کن و بگو مانده‌ی پول کی پرداخت می‌شود."}},{"by":"AI tool","answer":"Incoterms 2020 apply. Payment: 30% in advance, 70% against a copy of the bill of lading.","present":["Year","Payment clear"],"fix":{"en":"Good payment term, but which rule, and which place? Add 'CFR Jebel Ali'.","tr":"Ödeme koşulu iyi ama hangi kural, hangi yer? 'CFR Jebel Ali' ekle.","fa":"شرط پرداخت خوب است، ولی کدام قاعده و کدام محل؟ «CFR Jebel Ali» را اضافه کن."}},{"by":"Good model","answer":"CFR Jebel Ali, Incoterms 2020. Payment: 30% in advance, 70% against a copy of the bill of lading.","present":["Rule and place","Year","Payment clear"],"fix":null}]},"speaking":{"id":"sales-2-2","course":"sales","unit":"sales-2-2","topic":{"en":"Explaining two options to a buyer","tr":"Bir alıcıya iki seçeneği anlatmak","fa":"توضیح دو گزینه به خریدار"},"warmup":{"en":"Which terms do you or your company usually use? Do you know where the risk passes?","tr":"Sen ya da şirketin genellikle hangi koşulları kullanıyorsunuz? Riskin nerede geçtiğini biliyor musun?","fa":"تو یا شرکتت معمولاً از چه شرایطی استفاده می‌کنید؟ می‌دانی ریسک کجا منتقل می‌شود؟"},"questions":[{"en":"A buyer asks: 'What's the difference between your FOB and your CIF price?' Explain who pays and who books the ship.","tr":"Bir alıcı soruyor: 'What's the difference between your FOB and your CIF price?' Kimin ödediğini ve gemiyi kimin ayarladığını açıkla.","fa":"خریداری می‌پرسد: «What's the difference between your FOB and your CIF price?» توضیح بده چه کسی می‌پردازد و چه کسی کشتی را رزرو می‌کند."},{"en":"Compare them with two comparatives. Say which one fits a buyer with no forwarder.","tr":"İkisini iki karşılaştırmayla kıyasla. Nakliyecisi olmayan bir alıcıya hangisinin uyduğunu söyle.","fa":"با دو صفت تفضیلی مقایسه‌شان کن. بگو کدام برای خریداری که فورواردر ندارد مناسب‌تر است."},{"en":"The buyer asks for open account on the first order. Say no politely, and offer a safer term.","tr":"Alıcı ilk sipariş için açık hesap istiyor. Kibarca hayır de ve daha güvenli bir koşul öner.","fa":"خریدار برای سفارش اول حساب باز می‌خواهد. مؤدبانه نه بگو و شرطی امن‌تر پیشنهاد کن."}],"followups":[{"en":"Which rule and which payment term would you offer your next buyer, and why?","tr":"Bir sonraki alıcına hangi kuralı ve hangi ödeme koşulunu önerirdin, neden?","fa":"به خریدار بعدی‌ات کدام قاعده و کدام شرط پرداخت را پیشنهاد می‌کنی و چرا؟"}],"expressions":[{"phrase":"The risk passes when ...","meaning":{"en":"Says where the risk passes.","tr":"Riskin nerede geçtiğini söyler.","fa":"می‌گوید ریسک کجا منتقل می‌شود."}},{"phrase":"... is slightly more expensive, but ...","meaning":{"en":"Compares fairly.","tr":"Adil biçimde karşılaştırır.","fa":"منصفانه مقایسه می‌کند."}},{"phrase":"For a first order, we ask for ...","meaning":{"en":"Says no to risky terms politely.","tr":"Riskli koşullara kibarca hayır der.","fa":"مؤدبانه به شرایط پرریسک نه می‌گوید."}}],"model":"With FOB, you book the ship, and the risk passes when the goods are on board at Mersin. With CIF, we book the ship and pay for basic insurance to your port, but the risk still passes at Mersin. CIF is slightly more expensive, but it's simpler if you have no forwarder. For a first order, we ask for thirty percent in advance.","selfCheck":[{"en":"I said who pays and where the risk passes.","tr":"Kimin ödediğini ve riskin nerede geçtiğini söyledim.","fa":"گفتم چه کسی می‌پردازد و ریسک کجا منتقل می‌شود."},{"en":"I named a real place, not only a rule.","tr":"Yalnızca kural değil, gerçek bir yer de söyledim.","fa":"فقط قاعده نگفتم، محل واقعی را هم گفتم."},{"en":"I compared correctly: -er or more, never both.","tr":"Doğru karşılaştırdım: -er ya da more, ikisi birden değil.","fa":"درست مقایسه کردم: یا ‎-er یا more، نه هر دو."},{"en":"I said no to a risky term and offered another.","tr":"Riskli bir koşula hayır dedim ve başka bir koşul önerdim.","fa":"به یک شرط پرریسک نه گفتم و شرط دیگری پیشنهاد کردم."}]},"writing":{"id":"c-sales-2-2-w","course":"sales","unit":"sales-2-2","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Two delivery options for a buyer","tr":"Bir alıcı için iki teslim seçeneği","fa":"دو گزینه‌ی تحویل برای خریدار"},"portfolio":null,"prompt":{"en":"Use your own product and port, or: 20 pallets of dates from Bandar Abbas to Jebel Ali (Dubai); FOB USD 2.40 a kilo; CFR USD 2.65 a kilo. Write to the buyer (60-80 words): explain both options with the rule, place and year, compare them fairly, recommend one and state your payment term.","tr":"Kendi ürününü ve limanını ya da şunu kullan: Bender Abbas'tan Cebel Ali'ye (Dubai) 20 palet hurma; FOB kilosu 2,40 dolar; CFR kilosu 2,65 dolar. Alıcıya yaz (60-80 kelime): iki seçeneği kural, yer ve yılla açıkla, adil biçimde karşılaştır, birini öner ve ödeme koşulunu belirt.","fa":"از محصول و بندر خودت استفاده کن، یا از این نمونه: ۲۰ پالت خرما از بندرعباس به جبل علی (دبی)؛ FOB کیلویی ۲٫۴۰ دلار؛ CFR کیلویی ۲٫۶۵ دلار. به خریدار بنویس (۶۰ تا ۸۰ کلمه): هر دو گزینه را با قاعده، محل و سال توضیح بده، منصفانه مقایسه کن، یکی را پیشنهاد کن و شرط پرداختت را بگو."},"model":"Dear Mr Al Mazrouei,\n\nWe can offer two options under Incoterms 2020. FOB Bandar Abbas is USD 2.40 a kilo: you book the ship and insurance. CFR Jebel Ali is USD 2.65 a kilo: we book the ship. CFR is slightly more expensive, but it is simpler, so I recommend it for a first order. In both, the risk passes on board at Bandar Abbas. Payment is 30% in advance and 70% against a copy of the bill of lading.\n\nBest regards","frame":"Dear ___,\n\nWe can offer two options under Incoterms 2020. ___ is ___: you ___. ___ is ___: we ___. ___ is slightly more expensive, but ___, so I recommend ___. The risk passes ___. Payment is ___.\n\nBest regards","words":[{"word":"Incoterms 2020"},{"word":"slightly more expensive"},{"word":"the risk passes"}],"minWords":60,"minSentences":5,"rubric":["Task done: two options, a recommendation, where the risk passes, a payment term","Organised: option, option, comparison, payment","Language: comparatives and as ... as are correct","Tone: fair, and exact with every figure and place"],"rubricI18n":{"tr":["Görev: iki seçenek, bir öneri, riskin geçtiği yer, ödeme koşulu","Düzen: seçenek, seçenek, karşılaştırma, ödeme","Dil: karşılaştırmalar ve as ... as doğru","Üslup: adil, her rakam ve yerde net"],"fa":["کامل بودن کار: دو گزینه، یک پیشنهاد، محل انتقال ریسک، شرط پرداخت","نظم: گزینه، گزینه، مقایسه، پرداخت","زبان: صفت‌های تفضیلی و as ... as درست‌اند","لحن: منصفانه، و دقیق در هر عدد و محل"]}},"exit":{"id":"c-sales-2-2-x","course":"sales","unit":"sales-2-2","type":"exit","items":[{"from":"sales-2-2","kind":"mcq","prompt":"Which line is written correctly?","options":["FOB Mersin Port, Incoterms 2020","Delivered, best terms, as agreed","FOB, as usual, at the normal port"],"correct":0,"point":1,"why":{"en":"'FOB Mersin Port, Incoterms 2020' gives the rule, the place and the version. 'Best terms' and 'as usual' leave the risk point open.","tr":"'FOB Mersin Port, Incoterms 2020' kuralı, yeri ve sürümü verir. 'Best terms' ve 'as usual' risk noktasını belirsiz bırakır.","fa":"«FOB Mersin Port, Incoterms 2020» قاعده، محل و نسخه را می‌گوید. «best terms» و «as usual» معلوم نمی‌کنند ریسک کجا منتقل می‌شود."}},{"from":"sales-2-2","kind":"blank","prompt":"For an exporter, open account is not as safe ___ cash in advance.","options":["than","as","like"],"correct":1,"point":2,"why":{"en":"as: 'not as ... as' compares two things. 'Than' goes with a comparative like 'safer', and 'like' does not compare here.","tr":"as: 'not as ... as' iki şeyi karşılaştırır. 'Than' 'safer' gibi bir karşılaştırma sıfatıyla gelir; 'like' burada karşılaştırma yapmaz.","fa":"as درست است، چون not as ... as دو چیز را مقایسه می‌کند. than با صفت تفضیلی مثل safer می‌آید و like اینجا مقایسه نمی‌کند."}},{"from":"sales-2-2","kind":"mcq","prompt":"Which payment is safest for the seller?","options":["Open account","Documentary collection","Cash in advance"],"correct":2,"point":1,"why":{"en":"Cash in advance: the seller has the money before the goods leave. With open account, the seller ships first and waits to be paid.","tr":"Cash in advance: satıcı mal yola çıkmadan parayı alır. Open account'ta satıcı önce gönderir, sonra ödemeyi bekler.","fa":"Cash in advance امن‌ترین است، چون فروشنده قبل از ارسال کالا پول را دارد. در open account فروشنده اول می‌فرستد و بعد منتظر پول می‌ماند."}},{"from":"sales-2-1","kind":"blank","prompt":"Who ___ on new suppliers in your company?","options":["decide","is decide","decides"],"correct":2,"point":2,"why":{"en":"decides: 'who' is the subject, so add -s and no 'do'. 'Decide' needs a plural subject; 'is decide' mixes two verbs.","tr":"decides: 'who' öznedir; -s eklenir, 'do' gelmez. 'Decide' çoğul özne ister; 'is decide' iki fiili karıştırır.","fa":"decides درست است، چون who فاعل است؛ پس ‎-s می‌گیرد و do نمی‌خواهد. decide فاعل جمع می‌خواهد و is decide دو فعل را قاطی می‌کند."}},{"from":"sales-1-3","kind":"mcq","prompt":"What should come before you offer anything?","options":["A summary of what the buyer needs","A discount to open the conversation","Your company history and your awards"],"correct":0,"point":1,"why":{"en":"A summary of the need: the buyer hears you understood before you offer. An early discount or your awards skip that step.","tr":"İhtiyacın özeti: alıcı, sen teklif vermeden önce onu anladığını duyar. Erken indirim ya da ödüllerin bu adımı atlar.","fa":"خلاصه‌ی نیاز خریدار؛ این‌طوری قبل از پیشنهاد می‌شنود که حرفش را فهمیده‌ای. تخفیف زودهنگام یا جایزه‌هایت این قدم را جا می‌اندازند."}},{"from":"sales-1-1","kind":"blank","prompt":"The bags are resealable, so your customers can ___ them many times.","options":["open","to open","opening"],"correct":0,"point":2,"why":{"en":"open: 'can' takes the plain verb. 'To open' and 'opening' cannot follow can.","tr":"open: 'can' yalın fiil alır. can'den sonra 'to open' ya da 'opening' gelmez.","fa":"open درست است، چون بعد از can فعل ساده می‌آید؛ to open و opening بعد از can نمی‌آیند."}}]},"explain":{"id":"c-sales-2-2-e","course":"sales","unit":"sales-2-2","type":"explain","level":"B1","title":{"en":"Incoterms and payment terms","tr":"Incoterms ve ödeme koşulları","fa":"اینکوترمز و شرایط پرداخت"},"objective":{"en":"After this lesson, you can explain who pays, who carries the risk and how the buyer pays, using Incoterms and payment terms.","tr":"Bu dersin sonunda Incoterms ve ödeme koşullarıyla kimin ödediğini, riski kimin taşıdığını ve alıcının nasıl ödediğini açıklayabileceksin.","fa":"بعد از این درس می‌توانی با اینکوترمز و شرایط پرداخت توضیح بدهی چه کسی هزینه می‌دهد، ریسک با کیست و خریدار چطور پرداخت می‌کند."},"hook":{"en":"An Incoterm says who pays for transport and where the risk passes to the buyer: from that point, any loss is the buyer's. So USD 40 FOB and USD 40 CIF are different offers: with CIF, the seller also pays sea freight and basic insurance.","tr":"Incoterm, taşımayı kimin ödediğini ve riskin alıcıya nerede geçtiğini söyler: o noktadan sonra her zarar alıcınındır. Bu yüzden 40 dolar FOB ile 40 dolar CIF farklı tekliflerdir: CIF'te navlunu ve temel sigortayı da satıcı öder.","fa":"اینکوترم می‌گوید هزینه‌ی حمل با کیست و ریسک کجا به خریدار منتقل می‌شود؛ از آن نقطه به بعد هر زیانی با خریدار است. برای همین ۴۰ دلار FOB و ۴۰ دلار CIF دو پیشنهاد متفاوت‌اند: در CIF کرایه‌ی حمل دریایی و بیمه‌ی پایه هم با فروشنده است."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Read a trade term in four steps","tr":"Bir ticaret terimini dört adımda oku","fa":"یک اصطلاح تجاری را در چهار قدم بخوان"},"steps":[{"en":"The later the seller's job ends, the more they pay: EXW at their door, DAP at the buyer's.","tr":"Satıcının işi ne kadar geç biterse o kadar çok öder: EXW'de kendi kapısında, DAP'ta alıcının yerinde.","fa":"هر چه کار فروشنده دیرتر تمام شود، هزینه‌ی بیشتری می‌دهد: در EXW کارش دم در خودش تمام می‌شود و در DAP در محل خریدار.","ex":"EXW: at the seller's door. FOB: on board. DAP: at the buyer's named place."},{"en":"Write the rule, the exact place and the year, or the cost is unclear.","tr":"Kuralı, tam yeri ve yılı yaz; yoksa maliyet belirsiz kalır.","fa":"قاعده، محل دقیق و سال را بنویس، وگرنه هزینه روشن نیست.","ex":"FCA Mersin Port, Incoterms 2020"},{"en":"Sea terms: FOB, CFR, CIF. Containers are usually handed over on land, so FCA or CIP suit.","tr":"FOB, CFR ve CIF deniz kurallarıdır. Konteyner genellikle karada teslim edilir; bu yüzden FCA ya da CIP uyar.","fa":"قاعده‌های FOB، CFR و CIF فقط برای حمل دریایی‌اند. کانتینر معمولاً در خشکی تحویل می‌شود؛ پس FCA یا CIP مناسب‌تر است.","ex":"Container by road and sea: CIP Dubai"},{"en":"Payment, safest to riskiest for the seller: advance, L/C, collection, open account. Less certain money means more risk.","tr":"Satıcı için en güvenliden en riskliye ödeme: peşin, akreditif, vesaik mukabili, açık hesap. Ödeme ne kadar belirsizse risk o kadar büyür.","fa":"این چهار روش پرداخت از امن‌ترین تا پرریسک‌ترین برای فروشنده مرتب شده‌اند: پیش‌پرداخت، اعتبار اسنادی، وصول اسنادی، حساب باز. هرچه دریافت پول نامطمئن‌تر باشد، ریسک بیشتر است.","ex":"Advance: before shipping. L/C: a bank pays against documents. Collection: banks release the documents when the buyer pays or signs to pay later. Open account: after delivery."}],"table":{"headers":{"en":["Rule","Seller pays up to","Risk passes"],"tr":["Kural","Satıcı nereye kadar öder","Risk nerede geçer"],"fa":["قاعده","فروشنده تا کجا می‌پردازد","ریسک کجا منتقل می‌شود"]},"rows":[["EXW","no transport: the buyer collects","when the goods are made available at the seller's site"],["FCA","handing to the buyer's carrier","at that handover"],["FOB","on board the ship","on board, at the port of loading"],["CFR / CIF","sea freight to the named port (CIF adds basic insurance)","on board, at the port of loading"],["CIP","carriage + broad insurance","with the first carrier"],["DAP","carriage to the named place","at the named place, ready to unload"]]}},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Comparing terms: cheaper than, not as safe as","tr":"Koşulları karşılaştırmak: cheaper than, not as safe as","fa":"مقایسه‌ی شرایط: cheaper than، not as safe as"},"steps":[{"en":"To compare, add -er + than to short adjectives.","tr":"Karşılaştırmak için kısa sıfatlara -er + than ekle.","fa":"برای مقایسه، به صفت کوتاه er اضافه کن و بعد than بیاور.","ex":"cheaper than, safer than"},{"en":"Long adjectives can't take -er, so use more ... than.","tr":"Uzun sıfatlar -er almaz; bu yüzden more ... than kullan.","fa":"صفت بلند er نمی‌گیرد، پس قبلش more و بعدش than بیاور.","ex":"more expensive than an FOB price"},{"en":"For equal or less, use (not) as + adjective + as.","tr":"Eşitlik ya da daha az için (not) as + sıfat + as kullan.","fa":"برای «به همان اندازه» یا «کمتر از»، صفت را بین (not) as و as بگذار.","ex":"Open account is not as safe as an L/C."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["short adjective + -er than","cheaper than, safer than"],["more + long adjective + than","more expensive than"],["(not) as + adjective + as","not as safe as cash in advance"],["twice / three times as ... as","twice as long as"]]},"tip":{"en":"Turkish 'daha' and Persian «تر» work with every adjective, so learners write 'more thick'. English chooses: -er for short words, more for long ones.","tr":"Türkçede her sıfat için 'daha' kullanırız: 'daha kalın', 'daha pahalı'. Bu yüzden İngilizcede 'more thick' ya da 'more thicker' yazılıyor. İngilizce seçer: kısa kelimelere -er, uzun kelimelere more.","fa":"در فارسی به هر صفتی «تر» اضافه می‌کنیم: «ضخیم‌تر»، «گران‌تر». برای همین خیلی از ما می‌نویسیم more thick یا more thicker. انگلیسی فرق می‌گذارد: کلمه‌ی کوتاه er می‌گیرد و قبل از کلمه‌ی بلند more می‌آید."},"wrong":"FOB is more cheap than CIF for the buyer.","right":"FOB is cheaper than CIF for the buyer."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Before you promise a term","tr":"Bir koşula söz vermeden önce","fa":"قبل از قول دادن درباره‌ی یک شرط"},"body":{"en":"The table shows 7 of the 11 rules. Ask your forwarder (who books your shipping) for real freight, and your bank which payment route and currency work. Incoterms don't cover price, ownership or payment, so put those in the contract. This is not legal or sanctions advice.","tr":"Tablo 11 kuralın 7'sini gösterir. Nakliyecine (sevkiyatını ayarlayan kişi) gerçek navlunu, bankana da hangi ödeme yolunun ve para biriminin işlediğini sor. Incoterms fiyatı, mülkiyeti ya da ödemeyi kapsamaz; bunları sözleşmeye yaz. Bu bir hukuki ya da yaptırım danışmanlığı değildir.","fa":"جدول ۷ قاعده از ۱۱ قاعده را نشان می‌دهد. کرایه‌ی واقعی را از فورواردرت (کسی که حمل را برایت رزرو می‌کند) بپرس و از بانکت بپرس کدام مسیر پرداخت و کدام ارز جواب می‌دهد. اینکوترمز قیمت، مالکیت و پرداخت را پوشش نمی‌دهد؛ پس آن‌ها را در قرارداد بنویس. این متن مشاوره‌ی حقوقی یا تحریمی نیست."},"phrases":[{"phrase":"The risk passes when ...","meaning":{"en":"Says where the risk passes.","tr":"Riskin nerede geçtiğini söyler.","fa":"می‌گوید ریسک کجا منتقل می‌شود."}},{"phrase":"... is slightly more expensive, but ...","meaning":{"en":"Compares fairly.","tr":"Adil biçimde karşılaştırır.","fa":"منصفانه مقایسه می‌کند."}},{"phrase":"For a first order, we ask for ...","meaning":{"en":"Says no to risky terms politely.","tr":"Riskli koşullara kibarca hayır der.","fa":"مؤدبانه به شرایط پرریسک نه می‌گوید."}},{"phrase":"letter of credit","meaning":{"en":"A bank's promise to pay when the right documents arrive.","tr":"akreditif","fa":"اعتبار اسنادی (ال‌سی)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Make the terms exact","tr":"Koşulları netleştir","fa":"شرایط را دقیق کن"},"item":"Price: 4 dollars per kilo, delivered. Payment: later. Your facts: you quote CIP Dubai; 30% in advance, 70% against a copy of the bill of lading.","answer":"Price: USD 4.00 per kilo, CIP Dubai, Incoterms 2020. Payment: 30% in advance, 70% against a copy of the bill of lading.","walk":[{"en":"'Delivered' is unclear. Name the rule and the place.","tr":"'Delivered' belirsizdir. Kuralı ve yeri belirt.","fa":"کلمه‌ی Delivered مبهم است؛ پس قاعده و محل را دقیق بگو."},{"en":"Add the year, so nobody uses older rules.","tr":"Yılı ekle ki kimse eski kuralları kullanmasın.","fa":"سال را اضافه کن تا کسی از قاعده‌های قدیمی استفاده نکند."},{"en":"'Later' is not a term. Say how much, when and against what.","tr":"'Later' bir koşul değildir. Ne kadar, ne zaman, neye karşılık söyle.","fa":"کلمه‌ی Later شرط پرداخت نیست. بگو چقدر، کی و در برابر چه چیزی پرداخت می‌شود."}]},"quick":{"prompt":"Under CIF, the seller pays the sea freight, but the risk passes ___.","options":["on board at the port of loading","at the buyer's warehouse in Dubai","when the buyer's bank has paid in full"],"correct":0,"why":{"en":"on board at the port of loading: a common trap. Who pays and who carries the risk can change at different places.","tr":"on board at the port of loading: sık düşülen bir tuzak. Kimin ödediği ve riski kimin taşıdığı farklı yerlerde değişebilir.","fa":"جواب on board at the port of loading است و اینجا دام رایجی هست: جایی که هزینه تمام می‌شود و جایی که ریسک منتقل می‌شود می‌توانند فرق داشته باشند."}},"remember":{"en":"Rule, place, year. How much, when, against what. You can now read a trade term, compare two offers and write exact terms.","tr":"Kural, yer, yıl. Ne kadar, ne zaman, neye karşılık. Artık bir ticaret terimini okuyabilir, iki teklifi karşılaştırabilir ve koşulları net yazabilirsin.","fa":"قاعده، محل و سال را بنویس. بگو چقدر، کی و در برابر چه چیزی پرداخت می‌شود. حالا می‌توانی یک اصطلاح تجاری را بخوانی، دو پیشنهاد را مقایسه کنی و شرایط را دقیق بنویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"How big is the difference? slightly, much, far","tr":"Fark ne kadar büyük? slightly, much, far","fa":"تفاوت چقدر است؟ slightly، much، far"},"steps":[{"en":"Small difference: slightly / a little / a bit + comparative.","tr":"Küçük fark: slightly / a little / a bit + karşılaştırma.","fa":"برای تفاوت کم، قبل از صفت تفضیلی slightly، a little یا a bit بیاور.","ex":"slightly more expensive"},{"en":"Big difference: much / far / a lot + comparative.","tr":"Büyük fark: much / far / a lot + karşılaştırma.","fa":"برای تفاوت زیاد، قبل از صفت تفضیلی much، far یا a lot بیاور.","ex":"far safer, a lot lower"},{"en":"Never very + comparative, never a lot of + comparative.","tr":"Asla very + karşılaştırma, asla a lot of + karşılaştırma.","fa":"قبل از صفت تفضیلی هرگز very یا a lot of نیاور.","ex":"much cheaper, not very cheaper"}],"table":{"headers":{"en":["How big?","Word","Example"],"tr":["Ne kadar?","Kelime","Örnek"],"fa":["چقدر؟","کلمه","مثال"]},"rows":[["small","slightly / a little / a bit","slightly more expensive per kilo"],["big","much / far / a lot / considerably","far safer for the seller"],["never","very + comparative","not: very cheaper"]]},"body":{"en":"B2: make one comparison exact with slightly, much or far.","tr":"B2: bir karşılaştırmayı slightly, much ya da far ile kesinleştir.","fa":"مسیر B2: یکی از مقایسه‌ها را با slightly، much یا far دقیق کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
